sp_widget.client_script:
api.controller = function($scope, $rootScope, $location, spUtil) {
    /* global document */
    var c = this;

    setTimeout(function() {
        $rootScope.$broadcast("sp.update.breadcrumbs", c.data.breadcrumbs);
    }, 1);

};

sp_widget.script:
/* global input, data, $sp, options */
(function() {

    data.breadcrumbsWidget = $sp.getWidget('breadcrumbs');

    data.breadcrumbs = [];

    var table = $sp.getParameter('table');
    var sys_id = $sp.getParameter('sys_id');

    var config = [
        {
            table: "x_hccc_hoc_ohs_hira_action",
            parentTable: "x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment",
            parentColumn: "parent_hazard",
            pageId: "hoc_hira_rl_form"
        },
        {
            table: "x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment",
            parentTable: "x_hccc_hoc_ohs_hira_case",
            parentColumn: "hira_case",
            pageId: "hoc_hira_rl_form"
        },
        {
            table: "x_hccc_hoc_ohs_hira_case",
            pageId: "hoc_hira_form"
        }
    ];

    function addBreadcrumb(tbl, id) {
        for (var i = 0; i < config.length; i++) {
            if (tbl === config[i].table) {
                var gr = new GlideRecord(tbl);

                if (id === "-1") { //new record
                    var parent = $sp.getParameter('parent');

                    data.breadcrumbs.unshift({
                        url: "",
                        label: "New record"
                    });

                    if (config[i].parentTable) {
                        addBreadcrumb(config[i].parentTable, parent);
                    }
                } else if (gr.get(id)) {
                    data.breadcrumbs.unshift({
                        url: "?id=" + config[i].pageId +
                            "&table=" + config[i].table +
                            "&sys_id=" + id +
                            "&parent_field=" + config[i].parentColumn +
                            "&parent=" + gr.getValue(config[i].parentColumn) +
							"&view=" + $sp.getParameter("view"),
                        label: gr.getDisplayValue("number")
                    });
                    if (config[i].parentTable) {
                        addBreadcrumb(config[i].parentTable, gr.getValue(config[i].parentColumn));
                    }
                }
            }
        }
    }

    if (table && sys_id) {
        addBreadcrumb(table, sys_id);
    }

    //get from options
    data.breadcrumbs.unshift({
        url: "?id=hoc_hira_cases",
        label: gs.getMessage("x_hccc_hoc_ohs.hira_cases") //gs.getMessage("HIRA Cases")
    });
})();
